/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { digits, isPalindromic, isUnsolved, numDigits, rational } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.ntheory.digits", () => {
  // a primitive result that no library call returned
  //   count_digits(1111339)
  //   => defaultdict(<class 'int'>, {1: 4, 3: 2, 9: 1})
  it.todo("count_digits(1111339)");
  // a primitive result that no library call returned
  //   count_digits(n, 16)
  //   => defaultdict(<class 'int'>, {15: 1, 10: 1})
  it.todo("count_digits(n, 16)");
  // a primitive result that no library call returned
  //   digits(35)
  //   => [10, 3, 5]
  it.todo("digits(35)");
  // a primitive result that no library call returned
  //   digits(-35)
  //   => [-10, 3, 5]
  it.todo("digits(-35)");
  // a primitive result that no library call returned
  //   digits(27, b=2)
  //   => [2, 1, 1, 0, 1, 1]
  it.todo("digits(27, b=2)");
  // a primitive result that no library call returned
  //   digits(35, digits=4)
  //   => [10, 0, 0, 3, 5]
  it.todo("digits(35, digits=4)");
  it("is_palindromic(88, 8)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
});

